package warranty

import "testing"

func TestReady(t *testing.T) {
	if !Ready() {
		t.Fatal("baseline not ready")
	}
}

// Package warranty 是本地保修资格与备件承诺的本地基线。
package warranty

// Ready 表示基线可以运行。
func Ready() bool { return true }

